// Apply storyline patches: node apply.js patch.json
// Patch = [{ id, state:{date,text:[],changed}, figures:[...], questions:[...], settle:[{date, settled:{...}}], status?, resolved? }]
const fs = require('fs');
const patches = JSON.parse(fs.readFileSync(process.argv[2], 'utf8'));
for (const p of patches) {
  const f = '/home/user/ainews/storylines/' + p.id + '.json';
  const s = JSON.parse(fs.readFileSync(f, 'utf8'));
  if (p.figures) { s.figures = s.figures || []; s.figures.push(...p.figures); }
  if (p.questions) { s.questions = s.questions || []; s.questions.push(...p.questions); }
  if (p.settle) for (const x of p.settle) {
    const q = (s.questions || []).find((q) => q.date === x.date);
    if (!q) { console.log('!! ' + p.id + ': no question dated ' + x.date); continue; }
    q.settled = x.settled;
  }
  if (p.state) { s.states = s.states || []; s.states.push(p.state); }
  if (p.status) s.status = p.status;
  if (p.resolved) s.resolved = p.resolved;
  fs.writeFileSync(f, JSON.stringify(s, null, 2) + '\n');
  console.log('ok ' + p.id + ' states=' + s.states.length + ' figs=' + (s.figures || []).length + ' qs=' + (s.questions || []).length);
}

