node -e "
const j=require('./data/2026-11-02.week.json');
const by={};for(const h of j.happened)by[h.id]=h;
for(const c of j.connects){
  const pool=c.items.map(i=>by[i].headline+' '+by[i].bullets.join(' ')).join(' ');
  const allowed=new Set((pool.replace(/,/g,'').match(/\d+(?:\.\d+)?/g)||[]));
  const text=c.explanation.join(' ').replace(/\"[^\"]*\"/g,' ');
  const bad=[...new Set((text.replace(/,/g,'').match(/\d+(?:\.\d+)?/g)||[]))].filter(n=>!allowed.has(n));
  console.log(c.id+' -> '+(bad.length?('UNSOURCED NUMBERS: '+bad.join(',')):'ok'));
}
console.log('summary words', j.summary.join(' ').split(/\s+/).length);
"

