import json,glob,re
for f in sorted(glob.glob('data/2026-1*.json'))+sorted(glob.glob('data/2026-11-0*.json')):
    if '.script' in f or '.week' in f: continue
    try: d=json.load(open(f))
    except: continue
    t=json.dumps(d)
    for kw in ['BARC','Astra safe','Scale AI','37.3']:
        if kw in t:
            for m in re.finditer(re.escape(kw),t):
                print(f,'|',kw,'|',t[max(0,m.start()-600):m.start()+600])
                print('===')
            break
EOF

